import { notFound } from "next/navigation";

import { SessionDetail } from "@/components/session-detail";
import { getDisplayCwd } from "@/lib/cwd";
import { getSession } from "@/lib/sessions";

export default async function SessionPage({
  params,
}: {
  params: Promise<{ id: string }>;
}) {
  const { id } = await params;
  const timestamp = Number.parseInt(id, 10);
  if (!Number.isFinite(timestamp)) {
    notFound();
  }

  const session = await getSession(timestamp);
  if (!session) {
    notFound();
  }

  return <SessionDetail displayCwd={getDisplayCwd()} session={session} />;
}

"use client";

import { getToolName, isToolUIPart } from "ai";
import { Edit3, FileText, Pencil, Search, Terminal } from "lucide-react";
import type { LucideIcon } from "lucide-react";
import ReactMarkdown from "react-markdown";
import remarkGfm from "remark-gfm";

import { Badge } from "@/components/ui/badge";
import type { CodifyUIMessage } from "@/lib/agent";

type CodifyMessagePart = CodifyUIMessage["parts"][number];

const toolIconMap: Record<string, LucideIcon> = {
  editFile: Edit3,
  grep: Search,
  readFile: FileText,
  shell: Terminal,
  writeFile: Pencil,
};

const formatToolInputSummary = (input: unknown): string => {
  if (input === null || input === undefined) {
    return "";
  }
  if (typeof input !== "object") {
    return String(input);
  }
  const record = input as Record<string, unknown>;
  if (typeof record.path === "string") {
    return record.path;
  }
  if (typeof record.command === "string") {
    return record.command;
  }
  if (typeof record.pattern === "string") {
    return `"${record.pattern}"${record.path ? ` · ${record.path}` : ""}`;
  }
  return JSON.stringify(record);
};

const formatToolOutputSummary = (
  toolName: string,
  output: unknown
): string | null => {
  if (output === null || output === undefined || typeof output !== "object") {
    return null;
  }
  const record = output as Record<string, unknown>;
  if (toolName === "grep" && typeof record.totalMatches === "number") {
    const matches = record.totalMatches;
    return `${matches} match${matches === 1 ? "" : "es"}`;
  }
  if (toolName === "readFile" && typeof record.bytes === "number") {
    return `${record.bytes} bytes${record.truncated ? " · truncated" : ""}`;
  }
  if (toolName === "writeFile" && typeof record.bytesWritten === "number") {
    return `${record.bytesWritten} bytes written`;
  }
  if (toolName === "editFile" && typeof record.replaced === "number") {
    return "done";
  }
  if (toolName === "shell" && typeof record.exitCode === "number") {
    return `exit ${record.exitCode}`;
  }
  return null;
};

const renderStatusBadge = (state: string, outputSummary: string | null) => {
  if (state === "output-error") {
    return <Badge variant="destructive">error</Badge>;
  }
  if (state === "input-streaming" || state === "input-available") {
    return <Badge variant="secondary">running…</Badge>;
  }
  return <Badge variant="outline">{outputSummary ?? "done"}</Badge>;
};

interface MessagePartProps {
  part: CodifyMessagePart;
}

export const MessagePart = ({ part }: MessagePartProps) => {
  if (part.type === "text") {
    return (
      <div className="prose prose-sm prose-neutral dark:prose-invert max-w-none prose-pre:bg-muted prose-pre:text-foreground prose-code:before:content-none prose-code:after:content-none">
        <ReactMarkdown remarkPlugins={[remarkGfm]}>{part.text}</ReactMarkdown>
      </div>
    );
  }

  if (isToolUIPart(part)) {
    const toolName = getToolName(part);
    const Icon = toolIconMap[toolName] ?? Terminal;
    const inputSummary = formatToolInputSummary(part.input);
    const outputSummary =
      part.state === "output-available"
        ? formatToolOutputSummary(toolName, part.output)
        : null;
    const statusBadge = renderStatusBadge(part.state, outputSummary);

    return (
      <div className="flex items-center gap-3 rounded-md border bg-muted/30 px-3 py-2">
        <Icon aria-hidden className="size-4 shrink-0 text-muted-foreground" />
        <div className="flex min-w-0 flex-1 items-baseline gap-2">
          <span className="font-mono font-medium text-sm">{toolName}</span>
          {inputSummary ? (
            <span className="truncate font-mono text-muted-foreground text-xs">
              {inputSummary}
            </span>
          ) : null}
        </div>
        {statusBadge}
      </div>
    );
  }

  return null;
};

"use client";

import { useChat } from "@ai-sdk/react";
import { DefaultChatTransport } from "ai";
import type { UIMessage } from "ai";
import { ArrowRight, Square } from "lucide-react";
import { useEffect, useLayoutEffect, useRef, useState } from "react";
import type { FormEvent, KeyboardEvent } from "react";

import { MessagePart } from "@/components/message-part";
import { Button } from "@/components/ui/button";
import { Textarea } from "@/components/ui/textarea";
import type { CodifyUIMessage } from "@/lib/agent";
import type { Session } from "@/lib/sessions";
import { cn } from "@/lib/utils";

interface SessionDetailProps {
  session: Session;
  displayCwd: string;
}

const formatTime = (iso: string | undefined): string => {
  if (!iso) {
    return "";
  }
  const date = new Date(iso);
  if (Number.isNaN(date.getTime())) {
    return "";
  }
  return date.toLocaleTimeString([], {
    hour: "2-digit",
    minute: "2-digit",
  });
};

const messageTime = (message: UIMessage): string => {
  const metadata = message.metadata as
    | { createdAt?: string; timestamp?: string }
    | undefined;
  return formatTime(metadata?.createdAt ?? metadata?.timestamp);
};

const isUnansweredFirstUser = (history: UIMessage[]): boolean =>
  history.length === 1 && history[0]?.role === "user";

const handleSubmitKeyDown = (event: KeyboardEvent<HTMLTextAreaElement>) => {
  if ((event.metaKey || event.ctrlKey) && event.key === "Enter") {
    event.preventDefault();
    event.currentTarget.form?.requestSubmit();
  }
};

interface MessageRowProps {
  message: CodifyUIMessage;
}

const MessageRow = ({ message }: MessageRowProps) => {
  const isUser = message.role === "user";
  const label = isUser ? "you" : "agent";
  const time = messageTime(message);

  return (
    <article className="flex items-start gap-3">
      <div
        className={cn(
          "flex min-w-0 flex-1 flex-col gap-2 rounded-md border px-4 py-3",
          isUser ? "bg-sky-50/50" : "bg-background"
        )}
      >
        <div className="flex items-baseline gap-2">
          <span className="font-semibold text-sm">{label}</span>
          {time ? (
            <span className="font-mono text-muted-foreground text-xs">
              {time}
            </span>
          ) : null}
        </div>
        {message.parts.map((part, index) => (
          <MessagePart
            // biome-ignore lint/suspicious/noArrayIndexKey: parts are positional within a single message
            key={index}
            part={part}
          />
        ))}
      </div>
    </article>
  );
};

export const SessionDetail = ({ session, displayCwd }: SessionDetailProps) => {
  const initialMessages = session.history as CodifyUIMessage[];

  const { messages, sendMessage, regenerate, status, stop, error } =
    useChat<CodifyUIMessage>({
      id: String(session.timestamp),
      messages: initialMessages,
      transport: new DefaultChatTransport({
        api: `/api/sessions/${session.timestamp}/chat`,
      }),
    });

  const [input, setInput] = useState("");
  const autoSentRef = useRef(false);
  const scrollEndRef = useRef<HTMLDivElement | null>(null);

  useEffect(() => {
    if (autoSentRef.current) {
      return;
    }
    if (status !== "ready") {
      return;
    }
    if (!isUnansweredFirstUser(initialMessages)) {
      return;
    }
    autoSentRef.current = true;
    void regenerate();
  }, [status, initialMessages, regenerate]);

  useLayoutEffect(() => {
    scrollEndRef.current?.scrollIntoView({ block: "end" });
  }, [messages]);

  const handleSubmit = (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    const trimmed = input.trim();
    if (trimmed.length === 0 || status !== "ready") {
      return;
    }
    setInput("");
    void sendMessage({ text: trimmed });
  };

  const isStreaming = status === "submitted" || status === "streaming";
  const composerDisabled = status !== "ready";

  return (
    <div className="flex h-full min-h-0 flex-1 flex-col">
      <header className="flex shrink-0 items-baseline gap-3 border-b px-6 py-4">
        <span className="font-semibold text-lg">{session.title}</span>
        <span className="font-mono text-muted-foreground text-sm">
          {displayCwd}
        </span>
      </header>

      <div
        className="min-h-0 flex-1 overflow-y-auto"
        data-slot="session-transcript"
      >
        <div className="mx-auto flex w-full max-w-3xl flex-col gap-6 py-6">
          {messages.map((message) => (
            <MessageRow key={message.id} message={message} />
          ))}
          {error ? (
            <p
              aria-live="polite"
              className="rounded-md border border-destructive/40 bg-destructive/10 px-3 py-2 text-destructive text-sm"
              role="alert"
            >
              {error.message}
            </p>
          ) : null}
          <div ref={scrollEndRef} />
        </div>
      </div>

      <form
        className="shrink-0 bg-background px-6 py-4"
        onSubmit={handleSubmit}
      >
        <div className="relative mx-auto w-full max-w-3xl">
          <Textarea
            aria-label="Prompt"
            className="min-h-24 resize-none pr-14"
            disabled={composerDisabled}
            onChange={(event) => setInput(event.target.value)}
            onKeyDown={handleSubmitKeyDown}
            placeholder="Send a message to the agent..."
            rows={3}
            value={input}
          />
          {isStreaming ? (
            <Button
              aria-label="Stop generation"
              className="absolute right-2 bottom-2"
              onClick={() => stop()}
              size="icon"
              type="button"
              variant="secondary"
            >
              <Square />
            </Button>
          ) : (
            <Button
              aria-label="Submit prompt"
              className="absolute right-2 bottom-2"
              disabled={composerDisabled || input.trim().length === 0}
              size="icon"
              type="submit"
            >
              <ArrowRight />
            </Button>
          )}
        </div>
      </form>
    </div>
  );
};

import { promises as fs } from "node:fs";

import { tool } from "ai";
import { z } from "zod";

import { resolveWithinProject } from "../shared";

export type EditFileTool = typeof editFileTool;

export const editFileTool = tool({
  description:
    "Replace an exact substring inside an existing file. The substring must occur exactly once. Use this for surgical edits instead of rewriting the entire file.",
  execute: async ({ path: target, oldText, newText }) => {
    const absolute = resolveWithinProject(target);
    const original = await fs.readFile(absolute, "utf-8");
    const firstIndex = original.indexOf(oldText);
    if (firstIndex === -1) {
      throw new Error(`oldText was not found in ${target}.`);
    }
    if (original.includes(oldText, firstIndex + 1)) {
      throw new Error(
        `oldText occurs more than once in ${target}; provide more context to make it unique.`
      );
    }
    const updated =
      original.slice(0, firstIndex) +
      newText +
      original.slice(firstIndex + oldText.length);
    await fs.writeFile(absolute, updated, "utf-8");
    return { path: target, replaced: 1 };
  },
  inputSchema: z.object({
    newText: z.string().describe("Replacement text"),
    oldText: z.string().describe("Substring that must occur exactly once"),
    path: z.string().describe("Path to the file, relative to the project root"),
  }),
});
